mapper.select:
select sid, app_id, waste_base_id, warehousing_ids, outbound_code, outbound_time, outbound_quantity, transport_org_id, transport_org_name, transport_person_id, transport_person_name, outbound_org_id, outbound_org_name, outbound_person_id, outbound_person_name, storage_position_code, storage_position_name, storage_position_type, container_code, container_name, status, measurement_unit_code, measurement_unit_name, container_number, warehousing_codes, destination_org_id, destination_org_name, file_id, year_tag, serial_number, remark, update_by, update_time, create_by, create_time, tenant_id, tenant_name, del_flag from hse_hazardous_waste_outbound where sid in
#{item}
and del_flag=0

select
sid,
app_id,
waste_base_id,
warehousing_ids,
outbound_code,
outbound_time,
outbound_quantity,
transport_org_id,
transport_org_name,
transport_person_id,
transport_person_name,
outbound_org_id,
outbound_org_name,
outbound_person_id,
outbound_person_name,
storage_position_code,
storage_position_name,
storage_position_type,
container_code,
container_name,
status,
measurement_unit_code,
measurement_unit_name,
container_number,
warehousing_codes,
destination_org_id,
destination_org_name,
file_id,
year_tag,
serial_number,
remark,
update_by,
update_time,
create_by,
create_time,
tenant_id,
tenant_name,
del_flag

from hse_hazardous_waste_outbound
where app_id = #{appId} and del_flag=0


    and sid = #{sid}


    and app_id = #{appId}


    and waste_base_id = #{wasteBaseId}


    and warehousing_ids = #{warehousingIds}


    and outbound_code = #{outboundCode}


    and outbound_time = #{outboundTime}


    and outbound_quantity = #{outboundQuantity}


    and transport_org_id = #{transportOrgId}


    and transport_org_name = #{transportOrgName}


    and transport_person_id = #{transportPersonId}


    and transport_person_name = #{transportPersonName}


    and outbound_org_id = #{outboundOrgId}


    and outbound_org_name = #{outboundOrgName}


    and outbound_person_id = #{outboundPersonId}


    and outbound_person_name = #{outboundPersonName}


    and storage_position_code = #{storagePositionCode}


    and storage_position_name = #{storagePositionName}


    and storage_position_type = #{storagePositionType}


    and container_code = #{containerCode}


    and container_name = #{containerName}


    and status = #{status}


    and measurement_unit_code = #{measurementUnitCode}


    and measurement_unit_name = #{measurementUnitName}


    and container_number = #{containerNumber}


    and warehousing_codes = #{warehousingCodes}


    and destination_org_id = #{destinationOrgId}


    and destination_org_name = #{destinationOrgName}


    and file_id = #{fileId}


    and year_tag = #{yearTag}


    and serial_number = #{serialNumber}


    and remark = #{remark}


    and update_by = #{updateBy}


    and update_time = #{updateTime}


    and create_by = #{createBy}


    and create_time = #{createTime}


    and tenant_id = #{tenantId}


    and tenant_name = #{tenantName}


    and del_flag = #{delFlag}

select
outbound.sid,
outbound.app_id as appId,
outbound.waste_base_id as wasteBaseId,
outbound.warehousing_ids as warehousingIds,
outbound.outbound_code as outboundCode,
outbound.transport_org_id as transportOrgId,
outbound.transport_org_name as transportOrgName,
outbound.transport_person_id as transportPersonId,
outbound.transport_person_name as transportPersonName,
outbound.outbound_org_id as outboundOrgId,
outbound.outbound_org_name as outboundOrgName,
outbound.outbound_person_id as outboundPersonId,
outbound.outbound_person_name as outboundPersonName,
outbound.storage_position_code as storagePositionCode,
outbound.storage_position_name as storagePositionName,
outbound.storage_position_type as storagePositionType,
outbound.container_code as containerCode,
outbound.container_name as containerName,
outbound.status,
outbound.measurement_unit_code as measurementUnitCode,
outbound.measurement_unit_name as measurementUnitName,
outbound.container_number as containerNumber,
outbound.outbound_quantity as outboundQuantity,
outbound.outbound_time as outboundTime,
outbound.warehousing_codes as warehousingCodes,
outbound.destination_org_id as destinationOrgId,
outbound.destination_org_name as destinationOrgName,
outbound.file_id as fileId,
outbound.year_tag,
outbound.serial_number,
outbound.remark,
outbound.update_by,
outbound.update_time,
outbound.create_by,
outbound.create_time,
outbound.tenant_id,
outbound.tenant_name,
outbound.del_flag,

base.waste_name as wasteBaseName,
directory.waste_code as wasteCode,
directory.name as wasteName,
directory.type as wasteType


from hse_hazardous_waste_outbound as outbound
left join hse_hazardous_waste_base base on base.sid = outbound.waste_base_id
left join hse_hazardous_waste_directory directory on base.directory_id = directory.sid

where outbound.app_id = #{appId} and outbound.del_flag = 0
and base.app_id = #{appId} and base.del_flag = 0
and directory.app_id = #{appId} and directory.del_flag = 0


    and (
    outbound.outbound_code like concat('%',#{keyWord},'%')
    or outbound.outbound_person_name like concat('%',#{keyWord},'%')
    or base.waste_name like concat('%',#{keyWord},'%')
    or directory.waste_code like concat('%',#{keyWord},'%')
    )




    and outbound.waste_base_id = #{wasteBaseId}


    and outbound.warehousing_ids = #{warehousingIds}


    and outbound.outbound_code = #{outboundCode}


    and outbound.outbound_time = #{outboundTime}


    and outbound.outbound_quantity = #{outboundQuantity}


    and outbound.transport_org_id = #{transportOrgId}


    and outbound.transport_org_name = #{transportOrgName}


    and outbound.transport_person_id = #{transportPersonId}


    and outbound.transport_person_name = #{transportPersonName}


    and outbound.outbound_org_id = #{outboundOrgId}


    and outbound.outbound_org_name = #{outboundOrgName}


    and outbound.outbound_person_id = #{outboundPersonId}


    and outbound.outbound_person_name = #{outboundPersonName}


    and outbound.storage_position_code = #{storagePositionCode}


    and outbound.storage_position_name = #{storagePositionName}


    and outbound.storage_position_type = #{storagePositionType}


    and outbound.container_code = #{containerCode}


    and outbound.container_name = #{containerName}


    and outbound.status = #{status}


    and outbound.measurement_unit_code = #{measurementUnitCode}


    and outbound.measurement_unit_name = #{measurementUnitName}


    and outbound.container_number = #{containerNumber}


    and outbound.warehousing_codes = #{warehousingCodes}


    and outbound.destination_org_id = #{destinationOrgId}


    and outbound.destination_org_name = #{destinationOrgName}


    and outbound.file_id = #{fileId}


    and outbound.year_tag = #{yearTag}


    and outbound.serial_number = #{serialNumber}



    and outbound.outbound_time >= #{searchStartDate}


    and outbound.outbound_time <= #{searchEndDate}


order by outbound.create_time desc

select sid, app_id, waste_base_id, warehousing_ids, outbound_code, outbound_time, outbound_quantity, transport_org_id, transport_org_name, transport_person_id, transport_person_name, outbound_org_id, outbound_org_name, outbound_person_id, outbound_person_name, storage_position_code, storage_position_name, storage_position_type, container_code, container_name, status, measurement_unit_code, measurement_unit_name, container_number, warehousing_codes, destination_org_id, destination_org_name, file_id, year_tag, serial_number, remark, update_by, update_time, create_by, create_time, tenant_id, tenant_name, del_flag
from hse_hazardous_waste_outbound where app_id = #{appId}
and year_tag = #{yearTag}
order by serial_number desc limit 1;
